-- Grade 10 curriculum seed — real chapter/topic lists for CBSE + AP/TS SSC.
--
-- Fills the shared `subject_templates` catalog so the syllabus wizard
-- (school_completion: generateSyllabusFromTemplates) materialises REAL chapters
-- and topics per school/year, and the Question Intelligence engine has real
-- chapters to target instead of the "Unit 1 / Unit 2" stub fallback.
--
-- Source: official NCERT (CBSE) and SCERT AP/Telangana (SSC) textbook tables of
-- contents — chapter/topic NAMES only, which are factual and public (no
-- copyrighted question content). One-time data; reading it costs no AI/tokens.
--
-- Idempotent: re-running refreshes chapters for the same (board, code, grade).
-- board codes: 'CBSE' (NCERT national) · 'SSC' (AP/TS state board, Telugu medium).

INSERT INTO subject_templates (board, subject_code, subject_name, category, grade_label, chapters) VALUES

